// ==================== 状态定义 ====================

/** 钩子状态枚举 */
enum HookState {
  IDLE = 'IDLE',           // 空闲状态，等待发射
  AIMING = 'AIMING',       // 瞄准状态，旋转中
  FIRING = 'FIRING',       // 发射状态，钩子伸出
  GRABBING = 'GRABBING',   // 抓取状态，钩中物品
  RETRACTING = 'RETRACTING', // 收回状态，带着物品返回
  STUCK = 'STUCK',         // 卡住状态，撞到障碍
  COOLDOWN = 'COOLDOWN'    // 冷却状态，收回后等待
}

/** 钩子方向 */
enum HookDirection {
  LEFT = 'LEFT',
  RIGHT = 'RIGHT'
}

/** 物品类型 */
enum ItemType {
  GOLD_SMALL = 'GOLD_SMALL',
  GOLD_MEDIUM = 'GOLD_MEDIUM',
  GOLD_LARGE = 'GOLD_LARGE',
  DIAMOND = 'DIAMOND',
  ROCK = 'ROCK',
  BOMB = 'BOMB',
  TREASURE = 'TREASURE'
}

// ==================== 事件定义 ====================

/** 状态机事件 */
interface HookEvent {
  type: string;
  payload?: any;
}

interface FireEvent extends HookEvent {
  type: 'FIRE';
  payload: {
    angle: number;  // 发射角度
  };
}

interface HitItemEvent extends HookEvent {
  type: 'HIT_ITEM';
  payload: {
    itemType: ItemType;
    weight: number;
    value: number;
    itemId: string;
  };
}

interface HitObstacleEvent extends HookEvent {
  type: 'HIT_OBSTACLE';
  payload: {
    obstacleType: 'rock' | 'boundary';
  };
}

interface ReachOriginEvent extends HookEvent {
  type: 'REACH_ORIGIN';
}

interface TimeoutEvent extends HookEvent {
  type: 'TIMEOUT';
}

interface UseDynamiteEvent extends HookEvent {
  type: 'USE_DYNAMITE';
}

interface ResetEvent extends HookEvent {
  type: 'RESET';
}

// ==================== 状态机上下文 ====================

interface HookContext {
  // 位置信息
  x: number;
  y: number;
  angle: number;

  // 速度和力度
  speed: number;
  pullForce: number;

  // 当前抓取物品
  grabbedItem: {
    id: string;
    type: ItemType;
    weight: number;
    value: number;
  } | null;

  // 冷却时间
  cooldownRemaining: number;

  // 最大距离
  maxDistance: number;

  // 力量增益
  strengthMultiplier: number;
}

// ==================== 状态机实现 ====================

class HookStateMachine {
  private state: HookState = HookState.IDLE;
  private context: HookContext;
  private stateHistory: HookState[] = [];
  private eventHandlers: Map<string, Function> = new Map();

  constructor(initialContext: Partial<HookContext> = {}) {
    this.context = {
      x: 0,
      y: 0,
      angle: 0,
      speed: 5,
      pullForce: 100,
      grabbedItem: null,
      cooldownRemaining: 0,
      maxDistance: 500,
      strengthMultiplier: 1,
      ...initialContext
    };

    this.setupEventHandlers();
  }

  /** 初始化事件处理器 */
  private setupEventHandlers(): void {
    this.eventHandlers.set('FIRE', this.handleFire.bind(this));
    this.eventHandlers.set('HIT_ITEM', this.handleHitItem.bind(this));
    this.eventHandlers.set('HIT_OBSTACLE', this.handleHitObstacle.bind(this));
    this.eventHandlers.set('REACH_ORIGIN', this.handleReachOrigin.bind(this));
    this.eventHandlers.set('TIMEOUT', this.handleTimeout.bind(this));
    this.eventHandlers.set('USE_DYNAMITE', this.handleUseDynamite.bind(this));
    this.eventHandlers.set('RESET', this.handleReset.bind(this));
    this.eventHandlers.set('COOLDOWN_END', this.handleCooldownEnd.bind(this));
  }

  /** 状态转换 */
  private transition(newState: HookState): void {
    const oldState = this.state;
    this.stateHistory.push(oldState);
    this.state = newState;

    console.log(`[HookStateMachine] ${oldState} -> ${newState}`);

    // 触发状态进入动作
    this.onEnterState(newState);
  }

  /** 进入状态时的动作 */
  private onEnterState(state: HookState): void {
    switch (state) {
      case HookState.IDLE:
        this.context.grabbedItem = null;
        this.context.cooldownRemaining = 0;
        break;

      case HookState.FIRING:
        // 开始发射动画
        break;

      case HookState.GRABBING:
        // 触发抓取音效
        break;

      case HookState.RETRACTING:
        // 计算收回速度（受物品重量影响）
        if (this.context.grabbedItem) {
          const weightFactor = 1 / (1 + this.context.grabbedItem.weight / 100);
          this.context.speed *= weightFactor * this.context.strengthMultiplier;
        }
        break;

      case HookState.STUCK:
        // 显示卡住提示
        break;

      case HookState.COOLDOWN:
        this.context.cooldownRemaining = 0.5; // 0.5秒冷却
        break;
    }
  }

  /** 处理发射事件 */
  private handleFire(event: FireEvent): void {
    if (this.state !== HookState.IDLE && this.state !== HookState.AIMING) {
      console.warn(`[HookStateMachine] Cannot fire from state: ${this.state}`);
      return;
    }

    this.context.angle = event.payload.angle;
    this.transition(HookState.FIRING);
  }

  1/** 处理击中物品事件 */
  private handleHitItem(event: HitItemEvent): void {
    if (this.state !== HookState.FIRING) {
      console.warn(`[HookStateMachine] Cannot grab from state: ${this.state}`);
      return;
    }

    this.context.grabbedItem = {
      id: event.payload.itemId,
      type: event.payload.itemType,
      weight: event.payload.weight,
      value: event.payload.value
    };

    this.transition(HookState.GRABBING);

    // 立即开始收回
    setTimeout(() => {
      if (this.state === HookState.GRABBING) {
        this.transition(HookState.RETRACTING);
      }
    }, 100);
  }

  /** 处理撞到障碍物事件 */
  private handleHitObstacle(event: HitObstacleEvent): void {
    if (this.state !== HookState.FIRING) {
      console.warn(`[HookStateMachine] Cannot hit obstacle from state: ${this.state}`);
      return;
    }

    if (event.payload.obstacleType === 'boundary') {
      // 边界碰撞，自动收回
      this.transition(HookState.RETRACTING);
    } else {
      // 岩石等障碍，卡住
      this.transition(HookState.STUCK);
    }
  }

  /** 处理回到原点事件 */
  private handleReachOrigin(event: ReachOriginEvent): void {
    if (this.state !== HookState.RETRACTING) {
      console.warn(`[HookStateMachine] Cannot reach origin from state: ${this.state}`);
      return;
    }

    // 处理收集物品
    if (this.context.grabbedItem) {
      const value = this.context.grabbedItem.value * this.context.strengthMultiplier;
      console.log(`[HookStateMachine] Collected ${this.context.grabbedItem.type} worth ${value}`);
    }

    this.transition(HookState.COOLDOWN);
  }

  /** 处理超时事件 */
  private handleTimeout(event: TimeoutEvent): void {
    if (this.state === HookState.STUCK) {
      // 超时后自动收回
      this.transition(HookState.RETRACTING);
    }
  }

  /** 处理使用炸药事件 */
  private handleUseDynamite(event: UseDynamiteEvent): void {
    if (this.state !== HookState.STUCK && this.state !== HookState.GRABBING) {
      console.warn(`[HookStateMachine] Cannot use dynamite from state: ${this.state}`);
      return;
    }

    // 销毁当前物品
    this.context.grabbedItem = null;
    this.transition(HookState.RETRACTING);

    console.log(`[HookStateMachine] Dynamite used! Item destroyed.`);
  }

  /** 处理重置事件 */
  private handleReset(event: ResetEvent): void {
    this.context.grabbedItem = null;
    this.context.x = 0;
    this.context.y = 0;
    this.context.cooldownRemaining = 0;
    this.transition(HookState.IDLE);
  }

  /** 处理冷却结束事件 */
  private handleCooldownEnd(): void {
    if (this.state !== HookState.COOLDOWN) {
      return;
    }

    this.transition(HookState.IDLE);
  }

  /** 公共接口：发送事件 */
  public send(event: HookEvent): void {
    const handler = this.eventHandlers.get(event.type);
    if (!handler) {
      console.error(`[HookStateMachine] Unknown event type: ${event.type}`);
      return;
    }

    handler(event);
  }

  /** 公共接口：获取当前状态 */
  public getState(): HookState {
    return this.state;
  }

  /** 公共接口：获取上下文 */
  public getContext(): HookContext {
    return { ...this.context };
  }

  /** 公共接口：更新上下文 */
  public updateContext(updates: Partial<HookContext>): void {
    this.context = { ...this.context, ...updates };
  }

  /** 公共接口：应用增益效果 */
  public applyBuff(buff: {
    strengthMultiplier?: number;
    speedMultiplier?: number;
    maxDistanceMultiplier?: number;
  }): void {
    if (buff.strengthMultiplier) {
      this.context.strengthMultiplier *= buff.strengthMultiplier;
    }
    if (buff.speedMultiplier) {
      this.context.speed *= buff.speedMultiplier;
    }
    if (buff.maxDistanceMultiplier) {
      this.context.maxDistance *= buff.maxDistanceMultiplier;
    }
  }

  /** 公共接口：更新冷却时间 */
  public updateCooldown(deltaTime: number): void {
    if (this.state === HookState.COOLDOWN) {
      this.context.cooldownRemaining -= deltaTime;
      if (this.context.cooldownRemaining <= 0) {
        this.handleCooldownEnd();
      }
    }
  }
}

