/**
 * 状态转换图（ASCII艺术）
 * 
 *                    FIRE
 *    IDLE ────────────────────────> FIRING
 *      ↑                              │
 *      │                              │
 *      │ COOLDOWN_END            HIT_ITEM ─────> GRABBING
 *      │                              │              │
 *      │                              │              │
 *      │     USE_DYNAMITE        HIT_OBSTACLE        │
 *      │      (from STUCK)           │              │
 *      │                              ↓              ↓
 *  COOLDOWN <─── REACH_ORIGIN    STUCK <─────── RETRACTING
 *      ↑            ↑               │               ↑
 *      │            │               │               │
 *      │            └───────────────┘               │
 *      │                (USE_DYNAMITE)              │
 *      │                                             │
 *      └─────────────────────────────────────────────┘
 *                      (自动收回)
 */

// ==================== 使用示例 ====================

// 创建钩子状态机实例
const hook = new HookStateMachine({
  speed: 8,
  pullForce: 150,
  maxDistance: 600
});

// 发射钩子
hook.send({ type: 'FIRE', payload: { angle: 45 } });

// 击中金子
hook.send({
  type: 'HIT_ITEM',
  payload: {
    itemType: ItemType.GOLD_MEDIUM,
    weight: 50,
    value: 200,
    itemId: 'gold_123'
  }
});

// 回到原点
hook.send({ type: 'REACH_ORIGIN' });

// 使用力量增益卡
hook.applyBuff({ strengthMultiplier: 1.5 });

// 重置
hook.send({ type: 'RESET' });
